def find_counterexample(limit=6):
    import itertools, random
    for n in range(2, limit+1):
        vals = list(range(1, n*2+1))
        for a in itertools.permutations(vals, n):
            if len(set(a))<n: continue
            for b in itertools.permutations([x for x in vals if x not in a], n):
                # algorithm: sort a asc, b desc
                a_sorted = sorted(a)
                b_sorted = sorted(b, reverse=True)
                sums = [a_sorted[i]+b_sorted[i] for i in range(n)]
                if len(set(sums))<n:
                    return n, a, b, a_sorted, b_sorted, sums
    return None
